async function main(ctx) {
  const resp = ctx.lastOutputOf('get_shop_info') || {};

  // Connector endpoint select currently returns { shop: {...} }
  const raw = resp.body ?? null;
  const shop = raw && typeof raw === 'object' && raw.shop && typeof raw.shop === 'object' ? raw.shop : raw;

  const initial = ctx.lastOutputOf('__initial__') || {};
  const level = String(initial.detailLevel || 'minimal');

  if (!shop || typeof shop !== 'object' || level === 'full') {
    return shop;
  }

  // Curated minimal view (LLM-friendly)
  const s = shop;
  return {
    id: s.id,
    name: s.name,
    myshopify_domain: s.myshopify_domain,
    domain: s.domain,
    country: s.country,
    country_code: s.country_code,
    currency: s.currency,
    primary_locale: s.primary_locale,
    timezone: s.timezone,
    iana_timezone: s.iana_timezone,
    plan_name: s.plan_name,
    plan_display_name: s.plan_display_name,
    created_at: s.created_at,
    updated_at: s.updated_at
  };
}
